(()=>{const select=$('#particle-renderer'),label=document.createElement('label');label.id='bolt-branches-label';label.innerHTML='Lightning branches<input id="bolt-branches" type="number" min="0" max="8" step="1" value="0"><small>Branches stay inside the same sideways distance limit. With Instant off, Speed controls growth and lifetime controls maximum reach. Enable Collide with a surface to stop on impact.</small>';select.closest('label').after(label);const instant=document.createElement('div');instant.id='bolt-instant-controls';instant.innerHTML='<label class="switch-label">Instant movement<input id="bolt-instant" type="checkbox"></label><label id="bolt-reach-label">Instant bolt reach (cm)<input id="bolt-reach" type="number" min="1" max="10000" step="10" value="300"></label><small>Instant reaches its target in one update, stopping on impact. Lifetime controls how long it remains visible.</small>';label.after(instant);$('#bolt-instant').onchange=e=>{state.boltInstant=e.target.checked;sync();restart();persist();};$('#bolt-reach').onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<1||value>10000){e.target.value=state.boltLength??300;return;}state.boltLength=value;restart();persist();};$('#bolt-branches').onchange=e=>{const v=Number(e.target.value);if(!Number.isInteger(v)||v<0||v>8){e.target.value=state.boltBranches||0;return;}state.boltBranches=v;persist();};
const previous=sync;sync=()=>{previous();const bolt=state.renderer==='lightning';label.hidden=!bolt;instant.hidden=!bolt;$('#bolt-instant').checked=!!state.boltInstant;$('#bolt-reach').value=state.boltLength??300;$('#bolt-reach-label').hidden=!state.boltInstant;const amount=document.querySelector('[data-key=amount]');if(amount){amount.min=bolt?1:5;amount.step=1;amount.value=state.amount;amount.closest('label').querySelector('.label-row span').textContent=bolt?'Lightning bolts':'Particle amount';}const size=document.querySelector('[data-key=size]');if(size)size.closest('label').querySelector('.label-row span').textContent=bolt?'Bolt thickness (Particle size)':'Particle size';$('#advanced-motion').disabled=bolt;$('#advanced-sprite').closest('label').hidden=bolt;$('#advanced-shape').closest('label').hidden=bolt;$('#bolt-branches').value=state.boltBranches||0;const spread=document.querySelector('[data-key="spread"]');if(spread){spread.closest('label').querySelector('.label-row span').textContent=bolt?'Zigzags (Spread)':'Spread';if(bolt){const update=()=>$('#value-spread').textContent=Math.round(2+(state.spread-5)/95*30)+' bends';const input=spread.oninput;spread.oninput=e=>{input(e);update();};update();}}const radius=$('#advanced-radiusVariation').closest('label');radius.firstChild.textContent=bolt?'Maximum left / right distance (cm)':'Distance from center variation (%)';};const change=select.onchange;select.onchange=async e=>{await change(e);if(state.renderer==='lightning'){if(state.boltBranches===undefined){state.boltBranches=2;if(!state.radiusVariation)state.radiusVariation=30;}state.motion='aimed';state.simulation='cpu';persist();}restart();sync();};sync();})();
